# Due unità laboratoriali aggiuntive per ogni materia e anno.
for grade in grades:
 for ss,sub in subjects.items():
  first,second=sub[grade][0],sub[grade][1]
  sub[grade].extend([
   (f"Laboratorio autentico di {sub['name']}",
    f"Questa unità trasforma {first[0].lower()} e {second[0].lower()} in una sfida reale. Gli studenti osservano un problema, formulano domande, scelgono informazioni attendibili, costruiscono un prodotto e ne valutano l'efficacia con criteri condivisi.",
    f"La classe riceve una missione collegata a {first[0].lower()}: in gruppi assegna ruoli, prepara una soluzione verificabile, la presenta in novanta secondi e raccoglie un miglioramento proposto dai compagni.",
    "Dividere il lavoro senza condividere il ragionamento o valutare solo l'aspetto finale."),
   (f"Progetto interdisciplinare: {sub['name']} nel mondo",
    f"Un progetto guidato collega {sub['name'].lower()} a lingua, cittadinanza, dati e creatività. Si parte da una domanda autentica, si confrontano almeno due fonti, si produce una rappresentazione visiva e si difende una conclusione davanti a un pubblico.",
    f"Domanda-progetto: in quale modo {second[0].lower()} influenza una scelta della nostra comunità? Il prodotto finale comprende una mappa, un dato commentato, un esempio e una proposta concreta.",
    "Creare collegamenti decorativi, copiare informazioni o presentare conclusioni senza prove.")
  ])

def slugify(s):
 return re.sub(r"[^a-z0-9]+","-",s.lower()).strip("-")

def diagram(path,title,theory,accent):
 words=theory.split()
 labels=[" ".join(words[i:i+5]) for i in range(0,min(len(words),20),5)]
 while len(labels)<4: labels.append(title)
 boxes="".join(f'<g transform="translate({80+(i%2)*410} {150+(i//2)*210})"><rect width="330" height="130" rx="22" fill="#fff" stroke="{accent}" stroke-width="3"/><circle cx="42" cy="42" r="22" fill="{accent}"/><text x="42" y="49" text-anchor="middle" fill="white" font-size="18" font-weight="700">{i+1}</text><text x="78" y="42" font-size="17" font-weight="700" fill="#242421">{escape(title[:26])}</text><text x="30" y="86" font-size="14" fill="#555">{escape(labels[i])}</text><path d="M30 104 H290" stroke="#d9d4ca"/></g>' for i in range(4))
 arrows='<path d="M410 215 H485" stroke="#59636e" stroke-width="3" marker-end="url(#a)"/><path d="M245 280 V345" stroke="#59636e" stroke-width="3" marker-end="url(#a)"/><path d="M655 280 V345" stroke="#59636e" stroke-width="3" marker-end="url(#a)"/>'
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="900" height="650" viewBox="0 0 900 650" role="img" aria-labelledby="t d"><title id="t">{escape(title)}</title><desc id="d">Schema concettuale in quattro passaggi.</desc><defs><marker id="a" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#59636e"/></marker></defs><rect width="900" height="650" rx="34" fill="#f2efe8"/><text x="80" y="82" font-family="Georgia,serif" font-size="34" fill="#242421">{escape(title)}</text><text x="80" y="112" font-family="Arial,sans-serif" font-size="14" fill="#6c6a63">Mappa concettuale · Zorix Education</text>{arrows}{boxes}</svg>'''
 path.write_text(svg,encoding="utf-8")

deep_blocks=[
("Obiettivi di apprendimento","Al termine del percorso dovrai saper definire il concetto con precisione, riconoscerlo in situazioni nuove, applicarlo con un procedimento controllabile e spiegare perché la soluzione è valida. La padronanza non coincide con la memoria: richiede scelta consapevole degli strumenti e capacità di correggersi."),
("Prerequisiti e punto di partenza","Prima di affrontare l'unità richiama ciò che già conosci. Scrivi tre parole associate al titolo, formula una previsione e annota un dubbio. Questo rende visibile la differenza tra idea iniziale e comprensione raggiunta, e permette di collegare il nuovo contenuto alle conoscenze precedenti."),
("Spiegazione passo per passo","Scomponi il tema in quattro mosse: osserva gli elementi, descrivi le relazioni, applica la regola o il modello, verifica il risultato. Ogni passaggio deve poter essere espresso con una frase completa. Se non riesci a spiegare un passaggio, torna alla definizione e costruisci un esempio più semplice."),
("Linguaggio specifico","Usare il lessico disciplinare evita ambiguità. Per ogni termine prepara una definizione, un esempio, un non-esempio e una relazione con un'altra parola. Non basta riconoscere il vocabolo: devi impiegarlo correttamente in una spiegazione e distinguerlo dai termini vicini."),
("Metodo di studio attivo","Leggi una porzione breve, chiudi il testo e ricostruiscila senza guardare. Confronta, correggi in un colore diverso e ripeti dopo un intervallo. Alterna richiamo, esercizio e spiegazione orale. Evidenziare da solo produce familiarità, ma non dimostra che saprai recuperare l'informazione durante una prova."),
("Dal semplice al complesso","Comincia da un caso privo di eccezioni, poi varia un elemento alla volta. Confronta ciò che resta invariato e ciò che cambia. Infine affronta un problema in cui la strategia non è dichiarata. Questo passaggio allena il trasferimento: la capacità di usare una conoscenza fuori dall'esempio studiato."),
("Connessioni interdisciplinari","Cerca un collegamento basato su un'idea reale, non sulla semplice presenza della stessa parola. Specifica il concetto comune, mostra come funziona nelle due discipline e indica anche una differenza. Un buon collegamento aggiunge comprensione; uno debole è solo un salto di argomento."),
("Strategia per la verifica","Leggi due volte la consegna, sottolinea il verbo operativo, identifica dati e vincoli, pianifica prima di rispondere. Durante lo svolgimento rendi visibile il ragionamento. Alla fine controlla coerenza, unità, lessico, completezza e corrispondenza tra domanda e risposta."),
("Analisi profonda del concetto","Distingui definizione, proprietà, procedura e campo di validità. La definizione stabilisce che cosa è il concetto; le proprietà descrivono come si comporta; la procedura indica come usarlo; il campo di validità chiarisce quando il modello funziona e quando occorre modificarlo. Questa distinzione impedisce di applicare meccanicamente una regola fuori contesto."),
("Costruzione del modello mentale","Immagina il contenuto come una rete, non come una lista. Al centro colloca l'idea principale; intorno disponi cause, conseguenze, esempi, controesempi e limiti. Etichetta ogni freccia con un verbo preciso. Se due nodi non possono essere collegati da una frase sensata, il rapporto non è ancora compreso."),
("Esempio, controesempio e caso limite","Un esempio mostra che una definizione si applica; un controesempio rivela che una generalizzazione è falsa; un caso limite mette alla prova i confini del modello. Costruirli autonomamente è uno degli strumenti più potenti per passare da una conoscenza fragile a una comprensione trasferibile."),
("Diagnosi degli errori","Quando una risposta è sbagliata, non limitarti a sostituirla. Classifica l'errore: lettura della consegna, richiamo della regola, scelta della strategia, esecuzione, linguaggio o controllo. Scrivi il punto esatto in cui il ragionamento devia e la domanda che avrebbe permesso di accorgersene."),
("Laboratorio pratico","Progetta una piccola attività osservabile: stabilisci scopo, materiali o fonti, procedura, dati da raccogliere e criterio di conclusione. Mantieni separati ciò che osservi e ciò che interpreti. Documenta anche risultati inattesi: spesso sono la parte più informativa dell'esperienza."),
("Comunicazione orale","Prepara un intervento in tre tempi: una domanda iniziale che orienta, uno sviluppo con due idee e un esempio, una sintesi che torna alla domanda. Parla usando parole-chiave, non un testo imparato a memoria. Allenati a rispondere a «come lo sai?» e «quando non vale?»."),
("Scrittura disciplinare","Una risposta completa contiene affermazione, evidenza e ragionamento. L'affermazione risponde; l'evidenza porta dato, regola o dettaglio; il ragionamento mostra perché l'evidenza sostiene la risposta. Usa connettivi causali, avversativi e conclusivi per rendere visibile la struttura logica."),
("Confronto e classificazione","Costruisci una tabella con criteri espliciti, evitando categorie sovrapposte. Per ogni elemento indica somiglianze, differenze e un criterio decisivo. Una classificazione è utile quando permette di prevedere o spiegare qualcosa, non quando si limita a distribuire etichette."),
("Trasferimento a un contesto nuovo","Cambia superficie al problema conservandone la struttura: modifica personaggi, numeri, lingua, ambiente o mezzo di rappresentazione. Poi identifica ciò che resta identico. Se sai riconoscere la stessa struttura sotto forme diverse, la conoscenza è disponibile per situazioni autentiche."),
("Percorso di recupero e potenziamento","Se il risultato è incerto, torna a definizioni ed esempi minimi, usa lo schema e completa esercizi a scelta guidata. Se la padronanza è solida, cerca eccezioni, confronta fonti, crea un problema e valuta due strategie. Recupero e potenziamento lavorano sullo stesso concetto a profondità differenti."),
]

def unit_page(grade,ss,sub,i,item,prev_link,next_link):
 title,theory,example,error=item
 gname,num,phase=grades[grade]
 accent=["#3762e9","#0e9ca8","#2f8d5b","#b5632f"][i%4]
 diag=f"diagrams/{grade}-{ss}-{i+1}.svg"
 diagram(ROOT/diag,title,theory,accent)
 diag2=f"diagrams/{grade}-{ss}-{i+1}-laboratorio.svg"
 diagram(ROOT/diag2,"Laboratorio: "+title,example,accent)
 engagement=f'''<section class="engagement" data-topic="{escape(title)}"><div class="hook"><p class="eyebrow">Gancio iniziale · 3 minuti</p><h2>La domanda che accende la classe</h2><p>Immagina di dover convincere un compagno che <strong>{escape(title.lower())}</strong> serve davvero fuori dalla scuola. Quale oggetto, notizia, scelta o esperienza useresti come prova?</p><button class="challenge-button" type="button">Estrai una sfida casuale</button><p class="challenge-output" aria-live="polite">Premi il pulsante: la classe avrà 60 secondi per rispondere.</p></div><div class="mission"><p class="eyebrow">Missione studenti · 15 minuti</p><h2>Osserva → ipotizza → prova → racconta</h2><ol><li>In coppia, scrivete una previsione senza consultare il testo.</li><li>Usate la mappa SVG per cercare un indizio che confermi o smentisca.</li><li>Create un mini esempio e un controesempio.</li><li>Spiegate la scoperta in una frase di massimo venti parole.</li></ol></div><details class="teacher-panel"><summary>Modalità docente: scaletta pronta da presentare</summary><div class="teacher-grid"><div><strong>0–3 min · Sorprendere</strong><p>Mostra soltanto il titolo e raccogli tre ipotesi senza correggere.</p></div><div><strong>3–10 min · Modellare</strong><p>Pensa ad alta voce usando l'esempio: {escape(example)}</p></div><div><strong>10–25 min · Far fare</strong><p>Avvia la missione in coppia; chiedi a chi osserva di annotare il ragionamento.</p></div><div><strong>25–35 min · Confrontare</strong><p>Metti due soluzioni alla lavagna e fai cercare una somiglianza e una differenza.</p></div><div><strong>35–45 min · Consolidare</strong><p>Nomina il concetto, correggi questo errore: {escape(error)}</p></div><div><strong>Ultimi 3 min · Verificare</strong><p>Exit ticket: «Prima pensavo…, ora penso…, mi resta da capire…».</p></div></div></details><div class="quick-quiz"><p class="eyebrow">Quiz lampo</p><h2>Vero, falso o dipende?</h2><p>{escape(theory)}</p><button type="button" class="reveal-answer">Mostra come argomentare</button><p class="answer" hidden>Non basta scegliere: cita la definizione, costruisci un caso e indica il limite. Una risposta eccellente usa «perché» e «tuttavia».</p></div></section>'''
 blocks="".join(f'''<section class="lesson-block"><p class="eyebrow">{escape(h)}</p><h2>{escape(title)}: {escape(h.lower())}</h2><p>{escape(text)} Nel caso di <strong>{escape(title.lower())}</strong>, il nucleo da conservare è questo: {escape(theory)}</p><p>Prova ora a riformulare il punto usando il connettivo «perché», poi con «quindi» e infine con «tuttavia». Le tre formulazioni obbligano a distinguere causa, conseguenza e limite del modello.</p></section>''' for h,text in deep_blocks)
 glossary="".join(f"<tr><th>{escape(w.strip('.,;:').capitalize())}</th><td>Termine chiave da definire nel contesto di {escape(title)} e da collegare al modello dell'unità.</td><td>Scrivi un esempio e un non-esempio.</td></tr>" for w in theory.split()[:12])
 exercises="".join(f'''<li><strong>Livello {n}.</strong> {q} <details><summary>Traccia di soluzione</summary><p>Riparti dalla definizione: {escape(theory)} Usa l'esempio «{escape(example)}» come modello di procedimento, modificando dati e contesto. Concludi con un controllo esplicito.</p></details></li>''' for n,q in enumerate([
  f"Definisci {title} in massimo quattro righe e aggiungi un esempio.",
  f"Confronta un caso corretto di {title} con un caso che sembra simile ma non lo è.",
  "Costruisci una mappa con quattro nodi e tre relazioni etichettate.",
  f"Spiega perché questo errore è plausibile e come correggerlo: {error}",
  "Applica l'idea a una situazione quotidiana non citata nella pagina.",
  "Formula una domanda da verifica e scrivi i criteri di una risposta eccellente.",
  "Collega l'unità a un'altra materia indicando somiglianza e differenza.",
  "Prepara una spiegazione orale di tre minuti con apertura, sviluppo e sintesi."
 ],1))
 return f'''<!doctype html><html lang="it"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · {sub["name"]} · {gname}</title><meta name="description" content="Unità didattica approfondita: {escape(title)}."><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="course.css"><link rel="stylesheet" href="unit.css"><link rel="stylesheet" href="theme-cute.css"></head><body>{base.header()}<main><section class="unit-hero" style="--accent:{accent}"><a class="back" href="{grade}-{ss}.html">← {sub["name"]}</a><p class="eyebrow">{gname} · Unità {i+1}</p><h1>{escape(title)}</h1><p>{escape(theory)}</p></section><nav class="unit-nav" aria-label="Navigazione tra unità">{prev_link}<a href="{grade}-{ss}.html">Indice del corso</a>{next_link}</nav>{engagement}<article class="lesson"><section class="visual"><img src="{diag}" alt="Mappa concettuale di {escape(title)}"><p>Segui le frecce, poi prova a ridisegnare lo schema senza guardare.</p><img src="{diag2}" alt="Schema di laboratorio di {escape(title)}"><p>Usa il secondo schema per progettare una spiegazione o un’attività.</p></section><section class="lesson-block key"><p class="eyebrow">Il concetto centrale</p><h2>Che cosa devi davvero capire</h2><p>{escape(theory)}</p><div class="worked"><h3>Esempio completamente guidato</h3><p>{escape(example)}</p><ol><li>Individua la domanda e separa i dati utili.</li><li>Richiama la definizione pertinente e giustifica la scelta.</li><li>Procedi un passo alla volta, nominando l'operazione mentale svolta.</li><li>Controlla il risultato con un metodo differente o un caso limite.</li><li>Scrivi una frase conclusiva che risponda esattamente alla domanda.</li></ol></div><aside><strong>Errore ad alta frequenza</strong><p>{escape(error)}</p><p>Per evitarlo, fermati prima del calcolo o della risposta e chiediti quale definizione autorizza il passaggio.</p></aside></section>{blocks}<section class="lesson-block"><p class="eyebrow">Glossario operativo</p><h2>Le parole da saper usare</h2><div class="table-wrap"><table><thead><tr><th>Parola</th><th>Significato operativo</th><th>Prova di padronanza</th></tr></thead><tbody>{glossary}</tbody></table></div></section><section class="lesson-block exercises"><p class="eyebrow">Laboratorio</p><h2>Esercizi graduati con tracce</h2><ol>{exercises}</ol></section><section class="lesson-block final-check"><p class="eyebrow">Autovalutazione</p><h2>Quando l'unità è davvero acquisita</h2><ul><li>So spiegare il tema senza leggere.</li><li>So usare correttamente almeno otto parole del glossario.</li><li>So risolvere un caso nuovo e motivare ogni passaggio.</li><li>So riconoscere e correggere l'errore tipico.</li><li>So creare un collegamento interdisciplinare non forzato.</li></ul></section></article></main><footer><span>© Zorix Education</span><a href="index.html">Indice generale</a></footer><script src="interactive.js"></script></body></html>'''

def subject_index(grade,ss,sub):
 gname,num,phase=grades[grade]
 cards=[]
 for i,item in enumerate(sub[grade]):
  cards.append(f'''<a class="unit-card" href="{grade}-{ss}-{i+1}.html"><span>{i+1:02}</span><div><h2>{escape(item[0])}</h2><p>{escape(item[1])}</p></div><b>Apri l'unità →</b></a>''')
 return f'''<!doctype html><html lang="it"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{sub["name"]} · {gname}</title><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="course.css"><link rel="stylesheet" href="unit.css"><link rel="stylesheet" href="theme-cute.css"></head><body>{base.header()}<main><section class="course-hero"><a class="back" href="index.html#{grade}">← Indice generale</a><p class="eyebrow">{num} · {gname} · {phase}</p><h1>{sub["name"]}</h1><p class="course-lead">Sei unità indipendenti, ciascuna con attività coinvolgenti, guida docente e spiegazione estesa, schema SVG, esempio guidato, glossario, esercizi e autovalutazione.</p></section><section class="unit-index">{''.join(cards)}</section></main><footer><span>© Zorix Education</span><a href="index.html">Indice generale</a></footer><script src="interactive.js"></script></body></html>'''

for grade in grades:
 for ss,sub in subjects.items():
  units=sub[grade]
  for i,item in enumerate(units):
   prev_link=f'<a href="{grade}-{ss}-{i}.html">← Precedente</a>' if i else '<span></span>'
   next_link=f'<a href="{grade}-{ss}-{i+2}.html">Successiva →</a>' if i<len(units)-1 else '<span></span>'
   (ROOT/f"{grade}-{ss}-{i+1}.html").write_text(unit_page(grade,ss,sub,i,item,prev_link,next_link),encoding="utf-8")
  (ROOT/f"{grade}-{ss}.html").write_text(subject_index(grade,ss,sub),encoding="utf-8")

groups=[]
for grade,(gname,num,phase) in grades.items():
 cards=''.join(f'''<a class="catalog-card" href="{grade}-{ss}.html"><span class="catalog-icon">{sub["icon"]}</span><div><h3>{sub["name"]}</h3><p>6 unità separate · schemi SVG · esercizi</p></div><span>↗</span></a>''' for ss,sub in subjects.items())
 groups.append(f'''<section class="catalog-year" id="{grade}"><div class="catalog-heading"><p class="eyebrow">{num} · {phase}</p><h2>{gname}</h2><p>{len(subjects)} materie, ognuna divisa in quattro unità HTML indipendenti.</p></div><div class="catalog-grid">{cards}</div></section>''')
