def technical_drawing_svg(laboratory=False):
 title="Laboratorio di disegno tecnico" if laboratory else "Disegno tecnico"
 panels=[
  ("1 · STRUMENTI","Matita H/HB · righello","squadre · compasso"),
  ("2 · TIPI DI LINEA","continua: contorni","tratteggio: elementi nascosti"),
  ("3 · SCALA 1:2","reale 100 mm","disegno 50 mm"),
  ("4 · QUOTATURA","linee di misura","frecce · valore · unità")
 ]
 if laboratory:
  panels=[
   ("1 · OSSERVA","individua forma e misure","scegli la vista principale"),
   ("2 · IMPOSTA","squadra il foglio","stabilisci scala e margini"),
   ("3 · COSTRUISCI","traccia linee leggere","controlla parallelismi"),
   ("4 · COMPLETA","ripassa e quota","verifica · pulisci · firma")
  ]
 boxes=[]
 for i,(head,a,b) in enumerate(panels):
  x=60+(i%2)*420; y=150+(i//2)*220
  boxes.append(f'''<g transform="translate({x},{y})"><rect x="0" y="0" width="360" height="170" rx="18" fill="#ffffff" stroke="#0e9ca8" stroke-width="3"/><rect x="0" y="0" width="360" height="46" rx="18" fill="#0e9ca8"/><rect x="0" y="28" width="360" height="18" fill="#0e9ca8"/><text x="22" y="30" font-family="Arial, sans-serif" font-size="17" font-weight="700" fill="#ffffff">{head}</text><text x="22" y="82" font-family="Arial, sans-serif" font-size="16" fill="#242421">{a}</text><text x="22" y="112" font-family="Arial, sans-serif" font-size="16" fill="#242421">{b}</text><line x1="22" y1="137" x2="330" y2="137" stroke="#94a3b8" stroke-width="2"/><circle cx="22" cy="137" r="5" fill="#2563eb"/><circle cx="330" cy="137" r="5" fill="#22c55e"/></g>''')
 return f'''<?xml version="1.0" encoding="UTF-8"?><svg xmlns="http://www.w3.org/2000/svg" version="1.1" width="900" height="650" viewBox="0 0 900 650"><title>{title}</title><desc>Schema tecnico compatibile con browser mobili.</desc><rect x="0" y="0" width="900" height="650" fill="#f2efe8"/><text x="60" y="72" font-family="Georgia, serif" font-size="38" fill="#242421">{title}</text><text x="60" y="106" font-family="Arial, sans-serif" font-size="15" fill="#6c6a63">Zorix Education · schema SVG 1.1</text>{''.join(boxes)}</svg>'''

(ASSETS/"prima-tecnologia-informatica-2.svg").write_text(technical_drawing_svg(False),encoding="utf-8")
(ASSETS/"prima-tecnologia-informatica-2-laboratorio.svg").write_text(technical_drawing_svg(True),encoding="utf-8")
